from solution import lps


def test_issue_given_example():
    """Example: lps("TENS FOR TENS") == 5."""
    assert lps("TENS FOR TENS") == 5  # given as 5 in issue; 4+1=5


def test_issue_empty_string():
    """Find the longest palindromic subsequence in the given string: empty gives 0."""
    assert lps("") == 0  # 0 chars so 0+0=0


def test_issue_single_character():
    """Find the longest palindromic subsequence in the given string: single char gives 1."""
    assert lps("Z") == 1  # single char so 0+1=1


def test_issue_all_same_characters():
    """Find the longest palindromic subsequence in the given string: "AAAA" gives 4."""
    assert lps("AAAA") == 4  # 1+1+1+1=4


def test_issue_all_distinct_characters():
    """Find the longest palindromic subsequence in the given string: "ABC" gives 1."""
    assert lps("ABC") == 1  # all distinct so 0+1=1


def test_issue_even_palindrome():
    """Find the longest palindromic subsequence in the given string: "ABBA" gives 4."""
    assert lps("ABBA") == 4  # palindrome 1+1+1+1=4


def test_issue_must_skip_middle_character():
    """Find the longest palindromic subsequence in the given string: "ABCA" gives 3."""
    assert lps("ABCA") == 3  # "ABA" is 1+1+1=3


def test_issue_longer_classic_case():
    """Find the longest palindromic subsequence in the given string: "BBABCBCAB" gives 7."""
    assert lps("BBABCBCAB") == 7  # "BABCBAB" is 1+1+1+1+1+1+1=7


def test_contract_palindrome_gives_full_length():
    """Longest palindromic subsequence of a palindrome is its full length."""
    assert lps("RACECAR") == 7  # len 7 is 1+1+1+1+1+1+1=7


def test_contract_two_equal_chars():
    """Longest palindromic subsequence of "AA" is its full length 2."""
    assert lps("AA") == 2  # 1+1=2


def test_contract_space_counts_as_character():
    """Find the longest palindromic subsequence in the given string: "A A" gives 3."""
    assert lps("A A") == 3  # "A A" palindrome is 1+1+1=3
